import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
import fs from 'fs';
const [,, dir, width, q] = process.argv;
const b = await chromium.launch(); const p = await b.newPage();
for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.jpg'))) {
  const data = 'data:image/jpeg;base64,' + fs.readFileSync(`${dir}/${f}`).toString('base64');
  const out = await p.evaluate(async ({ data, width, q }) => {
    const img = new Image(); img.src = data; await img.decode();
    const w = Math.min(+width, img.naturalWidth), h = Math.round(img.naturalHeight * w / img.naturalWidth);
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const x = c.getContext('2d'); x.imageSmoothingQuality = 'high'; x.drawImage(img, 0, 0, w, h);
    return [c.toDataURL('image/webp', +q), w, h];
  }, { data, width, q });
  const buf = Buffer.from(out[0].split(',')[1], 'base64');
  fs.writeFileSync(`${dir}/${f.replace('.jpg', '.webp')}`, buf);
  console.log(f, out[1], out[2], buf.length);
}
await b.close();
EOF
