1	/* The faded photograph of the leading festival's city behind the top of the
2	 * page (planNG.css draws it; festivals.js says which photograph is whose).
3	 *
4	 * Each photograph gets its own <img> in the backdrop, made the first time its
5	 * city leads and kept after: moving back to a city shown before costs no
6	 * download, and the photograph leaving fades out under the one arriving
7	 * rather than vanishing. The one leaving stays lit until the one arriving has
8	 * decoded, and then the two swap in the same frame, so the fade is a
9	 * cross-fade and never runs through an empty band.
10	 */
11	
12	/**
13	 * Show `photo` (a CITY_PHOTOS entry) in `host`, or nothing when it is null.
14	 * @param {HTMLElement} host the backdrop element
15	 * @param {{src: string, position?: string} | null} photo
16	 */
17	export function showCityPhoto(host, photo) {
18	  const want = photo ? photo.src : "";
19	  if (host.dataset.showing === want) return;
20	  host.dataset.showing = want;
21	  const leaving = () => {
22	    for (const other of host.querySelectorAll("img.is-on")) other.classList.remove("is-on");
23	  };
24	  if (!photo) return leaving();
25	
26	  let img = [...host.querySelectorAll("img")].find((i) => i.dataset.src === photo.src);
27	  if (!img) {
28	    img = document.createElement("img");
29	    img.alt = "";
30	    img.decoding = "async";
31	    img.dataset.src = photo.src;
32	    if (photo.position) img.style.objectPosition = photo.position;
33	    img.src = photo.src;
34	    host.append(img);
35	  }
36	  const light = () => {
37	    if (host.dataset.showing !== photo.src) return;
38	    // Laid out at zero opacity first, so the class change is a transition
39	    // even for a photograph the cache hands back already decoded.
40	    void img.offsetWidth;
41	    leaving();
42	    img.classList.add("is-on");
43	  };
44	  img.decode().then(light, light);
45	}

